-- =====================================================================
-- 00_AJUSTE_ENTIDAD.SQL
-- Nuevo dato de referencia identificado en PP y CRP.
-- Entidad es consistente por meta en las fuentes analizadas.
-- =====================================================================

BEGIN;

CREATE TABLE IF NOT EXISTS "entidad" (
  "id_entidad" SMALLINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nombre_entidad" varchar(150) UNIQUE NOT NULL
);

ALTER TABLE "meta_proyecto"
  ADD COLUMN IF NOT EXISTS "id_entidad" smallint;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'meta_proyecto_id_entidad_fkey'
  ) THEN
    ALTER TABLE "meta_proyecto"
      ADD CONSTRAINT "meta_proyecto_id_entidad_fkey"
      FOREIGN KEY ("id_entidad") REFERENCES "entidad" ("id_entidad");
  END IF;
END $$;

CREATE INDEX IF NOT EXISTS "idx_meta_proyecto_id_entidad"
  ON "meta_proyecto" ("id_entidad");

COMMENT ON TABLE "entidad" IS
  'Catálogo de entidades distritales relacionadas con las metas y propuestas de Presupuestos Participativos.';

COMMENT ON COLUMN "meta_proyecto"."id_entidad" IS
  'Entidad relacionada con la meta según fuentes de Presupuestos Participativos; puede ser NULL si la fuente no la informa.';

COMMIT;
